1	"use client";
2	
3	import { useState, useEffect, useCallback, useRef } from "react";
4	import { useRouter } from "next/navigation";
5	import { OptionIcon } from "@/lib/option-icons";
6	import { logActivity } from "@/components/ActivityTracker";
7	import ReactMarkdown from "react-markdown";
8	import remarkBreaks from "remark-breaks";
9	
10	interface OptionChoice {
11	  label: string;
12	  value: string;
13	  cost?: number;
14	}
15	
16	interface Option {
17	  id: string;
18	  group_id: string;
19	  name: string;
20	  description?: string;
21	  icon?: string | null;
22	  option_type: "checkbox" | "select" | "multi_select" | "text" | "number" | "quantity" | "trip_cost";
23	  cost?: number;
24	  choices?: OptionChoice[];
25	  is_required: boolean;
26	  sort_order: number;
27	  depends_on_option_id?: string | null;
28	  max_total?: number | null;
29	}
30	
31	interface OptionGroup {
32	  id: string;
33	  trip_id: string;
34	  name: string;
35	  description?: string;
36	  icon?: string | null;
37	  sort_order: number;
38	}
39	
40	interface OptionSettings {
41	  selection_deadline: string | null;
42	  is_open: boolean;
43	}
44	
45	type SelectionValue = boolean | string | string[] | number | Record<string, number> | null;
46	
47	interface OptionSelectionFormProps {
48	  tripId: string;
49	}
50	
51	export default function OptionSelectionForm({ tripId }: OptionSelectionFormProps) {
52	  const router = useRouter();
53	  const [groups, setGroups] = useState<OptionGroup[]>([]);
54	  const [options, setOptions] = useState<Option[]>([]);
55	  const [settings, setSettings] = useState<OptionSettings>({ selection_deadline: null, is_open: true });
56	  const [selections, setSelections] = useState<Record<string, SelectionValue>>({});
57	  const [loading, setLoading] = useState(true);
58	  const [savingOptions, setSavingOptions] = useState<Record<string, "saving" | "saved" | "error">>({});
59	  const debounceTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({});
60	
61	  const isLocked = useCallback(() => {
62	    if (!settings.is_open) return true;
63	    if (settings.selection_deadline && new Date() > new Date(settings.selection_deadline)) return true;
64	    return false;
65	  }, [settings]);
66	
67	  // Fetch options and selections
68	  useEffect(() => {
69	    async function load() {
70	      try {
71	        const [optionsRes, selectionsRes] = await Promise.all([
72	          fetch(`/api/options?trip_id=${tripId}`),
73	          fetch(`/api/selections?trip_id=${tripId}`),
74	        ]);
75	
76	        if (optionsRes.ok) {
77	          const optionsData = await optionsRes.json();
78	          setGroups(optionsData.groups || []);
79	          setOptions(optionsData.options || []);
80	          setSettings(optionsData.settings || { selection_deadline: null, is_open: true });
81	        }
82	
83	        if (selectionsRes.ok) {
84	          const selectionsData = await selectionsRes.json();
85	          const selMap: Record<string, SelectionValue> = {};
86	          for (const [optionId, sel] of Object.entries(selectionsData.selections || {})) {
87	            selMap[optionId] = (sel as { value: SelectionValue }).value;
88	          }
89	          setSelections(selMap);
90	        }
91	      } finally {
92	        setLoading(false);
93	      }
94	    }
95	    load();
96	  }, [tripId]);
97	
98	  const saveSelection = useCallback(async (optionId: string, value: SelectionValue) => {
99	    setSavingOptions((prev) => ({ ...prev, [optionId]: "saving" }));
100	    try {
101	      const res = await fetch("/api/selections", {
102	        method: "PUT",
103	        headers: { "Content-Type": "application/json" },
104	        body: JSON.stringify({
105	          trip_id: tripId,
106	          option_id: optionId,
107	          value: value === false ? null : value,
108	        }),
109	      });
110	
111	      if (!res.ok) {
112	        const data = await res.json();
113	        throw new Error(data.error || "Save failed");
114	      }
115	
116	      logActivity("option_selection", "/options", { option_id: optionId });
117	      setSavingOptions((prev) => ({ ...prev, [optionId]: "saved" }));
118	      setTimeout(() => {
119	        setSavingOptions((prev) => {
120	          const next = { ...prev };
121	          if (next[optionId] === "saved") delete next[optionId];
122	          return next;
123	        });
124	      }, 1500);
125	    } catch {
126	      setSavingOptions((prev) => ({ ...prev, [optionId]: "error" }));
127	      // Revert optimistic update by refetching
128	      const selectionsRes = await fetch(`/api/selections?trip_id=${tripId}`);
129	      if (selectionsRes.ok) {
130	        const selectionsData = await selectionsRes.json();
131	        const selMap: Record<string, SelectionValue> = {};
132	        for (const [oid, sel] of Object.entries(selectionsData.selections || {})) {
133	          selMap[oid] = (sel as { value: SelectionValue }).value;
134	        }
135	        setSelections(selMap);
136	      }
137	      setTimeout(() => {
138	        setSavingOptions((prev) => {
139	          const next = { ...prev };
140	          if (next[optionId] === "error") delete next[optionId];
141	          return next;
142	        });
143	      }, 3000);
144	    }
145	  }, [tripId]);
146	
147	  // Check if a dependency is satisfied (parent option is selected)
148	  const isDependencySatisfied = useCallback((option: Option): boolean => {
149	    if (!option.depends_on_option_id) return true;
150	    const parentVal = selections[option.depends_on_option_id];
151	    if (parentVal === null || parentVal === undefined || parentVal === false) return false;
152	    if (Array.isArray(parentVal) && parentVal.length === 0) return false;
153	    if (
154	      typeof parentVal === "object" &&
155	      !Array.isArray(parentVal) &&
156	      Object.values(parentVal as Record<string, number>).every((n) => !n || n <= 0)
157	    ) return false;
158	    return true;
159	  }, [selections]);
160	
161	  const handleChange = useCallback((optionId: string, value: SelectionValue, debounce = false) => {
162	    if (isLocked()) return;
163	
164	    setSelections((prev) => ({ ...prev, [optionId]: value }));
165	
166	    // If deselecting, cascade-clear any dependent options
167	    const isQuantityEmpty =
168	      value !== null &&
169	      typeof value === "object" &&
170	      !Array.isArray(value) &&
171	      Object.values(value as Record<string, number>).every((n) => !n || n <= 0);
172	    const isDeselecting =
173	      value === null ||
174	      value === false ||
175	      value === undefined ||
176	      (Array.isArray(value) && value.length === 0) ||
177	      isQuantityEmpty;
178	    if (isDeselecting) {
179	      const dependents = options.filter((o) => o.depends_on_option_id === optionId);
180	      for (const dep of dependents) {
181	        const depVal = selections[dep.id];
182	        if (depVal !== null && depVal !== undefined && depVal !== false) {
183	          setSelections((prev) => ({ ...prev, [dep.id]: null }));
184	          saveSelection(dep.id, null);
185	        }
186	      }
187	    }
188	
189	    if (debounce) {
190	      if (debounceTimers.current[optionId]) {
191	        clearTimeout(debounceTimers.current[optionId]);
192	      }
193	      debounceTimers.current[optionId] = setTimeout(() => {
194	        saveSelection(optionId, value);
195	      }, 300);
196	    } else {
197	      saveSelection(optionId, value);
198	    }
199	  }, [isLocked, saveSelection, options, selections]);
200	
201	  // Cost calculation
202	  const calculateCost = useCallback(() => {
203	    let total = 0;
204	    for (const opt of options) {
205	      const val = selections[opt.id];
206	      if (val === null || val === undefined) continue;
207	
208	      if ((opt.option_type === "checkbox" || opt.option_type === "trip_cost") && val === true) {
209	        total += opt.cost ? Number(opt.cost) : 0;
210	      } else if (opt.option_type === "select" && typeof val === "string") {
211	        const matched = (opt.choices || []).find((c) => c.value === val);
212	        if (matched?.cost) total += Number(matched.cost);
213	      } else if (opt.option_type === "multi_select" && Array.isArray(val)) {
214	        for (const v of val) {
215	          const matched = (opt.choices || []).find((c) => c.value === v);
216	          if (matched?.cost) total += Number(matched.cost);
217	        }
218	      }
219	    }
220	    return total;
221	  }, [options, selections]);
222	
223	  // Deadline helpers
224	  const deadlineDate = settings.selection_deadline ? new Date(settings.selection_deadline) : null;
225	  const now = new Date();
226	  const daysUntilDeadline = deadlineDate
227	    ? Math.ceil((deadlineDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
228	    : null;
229	
230	  const formatDeadline = (dateStr: string) => {
231	    const d = new Date(dateStr);
232	    return d.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
233	  };
234	
235	  const locked = isLocked();
236	  const totalCost = calculateCost();
237	
238	  const isAnswered = (opt: Option): boolean => {
239	    const val = selections[opt.id];
240	    if (val === null || val === undefined) return false;
241	    if (opt.option_type === "checkbox" || opt.option_type === "trip_cost") return val === true;
242	    if (opt.option_type === "select") return typeof val === "string" && val.length > 0;
243	    if (opt.option_type === "multi_select") return Array.isArray(val) && val.length > 0;
244	    if (opt.option_type === "text") return typeof val === "string" && val.trim().length > 0;
245	    if (opt.option_type === "number") return typeof val === "number" && !Number.isNaN(val);
246	    if (opt.option_type === "quantity") {
247	      // {} (explicit zero) counts as answered — the row exists
248	      return val !== null && typeof val === "object" && !Array.isArray(val);
249	    }
250	    return false;
251	  };
252	
253	  const requiredIncomplete = options.filter(
254	    (o) => o.is_required && isDependencySatisfied(o) && !isAnswered(o)
255	  );
256	  const allRequiredDone = requiredIncomplete.length === 0;
257	  const anySaving = Object.values(savingOptions).some((s) => s === "saving");
258	
259	  if (loading) {
260	    return (
261	      <div className="flex items-center justify-center py-20">
262	        <div className="w-8 h-8 border-4 border-green-600 border-t-transparent rounded-full animate-spin" />
263	      </div>
264	    );
265	  }
266	
267	  if (options.length === 0) {
268	    return (
269	      <div className="text-center py-16 text-gray-500">
270	        <svg className="w-12 h-12 mx-auto mb-3 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
271	          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
272	        </svg>
273	        <p className="text-lg font-medium text-gray-600">No options available for this trip yet.</p>
274	      </div>
275	    );
276	  }
277	
278	  // Group options by group_id, plus ungrouped
279	  const optionsByGroup: Record<string, Option[]> = {};
280	  for (const opt of options) {
281	    const gid = opt.group_id || "__ungrouped";
282	    if (!optionsByGroup[gid]) optionsByGroup[gid] = [];
283	    optionsByGroup[gid].push(opt);
284	  }
285	
286	  return (
287	    <div className="space-y-4">
288	      {/* Deadline banner */}
289	      {locked && (
290	        <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 flex items-start gap-3">
291	          <svg className="w-5 h-5 text-amber-600 mt-0.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
292	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m0 0v2m0-2h2m-2 0H10m9.364-7.364l-1.414 1.414M21 12h-2m0 0h-2m2 0v2m0-2V10M3.636 4.636l1.414 1.414M3 12h2m0 0h2m-2 0v2m0-2V10m9-6V2m0 2v2m0-2H10m2 0h2" />
293	            <rect x="5" y="11" width="14" height="10" rx="2" strokeWidth={2} />
294	            <path strokeLinecap="round" strokeWidth={2} d="M12 11V8" />
295	          </svg>
296	          <div>
297	            <p className="font-semibold text-amber-800">Selections are closed</p>
298	            <p className="text-sm text-amber-700 mt-0.5">Contact an admin to make changes.</p>
299	          </div>
300	        </div>
301	      )}
302	
303	      {!locked && deadlineDate && (
304	        <div className="bg-blue-50 border border-blue-200 rounded-2xl p-4">
305	          <p className="text-sm text-blue-800">
306	            <span className="font-medium">Selections due by {formatDeadline(settings.selection_deadline!)}</span>
307	            {daysUntilDeadline !== null && daysUntilDeadline > 0 && daysUntilDeadline <= 7 && (
308	              <span className="ml-2 text-blue-600 font-semibold">
309	                ({daysUntilDeadline} {daysUntilDeadline === 1 ? "day" : "days"} left)
310	              </span>
311	            )}
312	          </p>
313	        </div>
314	      )}
315	
316	      {/* Running cost total — sticks just below the global HeaderBar
317	          (h-14, sticky top-0) so the user always sees their running
318	          subtotal as they add items. */}
319	      <div className="bg-green-50 rounded-2xl border-2 border-green-600 shadow-md p-4 sticky top-14 z-20">
320	        <div className="flex items-center justify-between">
321	          <span className="text-sm font-semibold text-green-700 uppercase tracking-wide">Your estimated cost</span>
322	          <span className="text-2xl font-bold text-green-700 tabular-nums">
323	            ${totalCost.toLocaleString()}
324	          </span>
325	        </div>
326	      </div>
327	
328	      {/* Option groups */}
329	      {groups.map((group) => {
330	        const groupOptions = optionsByGroup[group.id];
331	        if (!groupOptions || groupOptions.length === 0) return null;
332	        const visibleOptions = groupOptions.filter((opt) => isDependencySatisfied(opt));
333	        if (visibleOptions.length === 0) return null;
334	
335	        return (
336	          <div key={group.id} className="space-y-3">
337	            <div>
338	              <div className="flex items-center gap-2">
339	                {group.icon && (
340	                  <div className="w-8 h-8 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center">
341	                    <OptionIcon iconKey={group.icon} className="w-5 h-5" />
342	                  </div>
343	                )}
344	                <h3 className="text-lg font-bold text-gray-900">{group.name}</h3>
345	              </div>
346	              {group.description && (
347	                <div className="text-sm text-gray-500 mt-1 mb-3 prose prose-sm prose-gray max-w-none">
348	                  <ReactMarkdown remarkPlugins={[remarkBreaks]}>{group.description}</ReactMarkdown>
349	                </div>
350	              )}
351	            </div>
352	
353	            {visibleOptions.map((opt) => (
354	              <OptionField
355	                key={opt.id}
356	                option={opt}
357	                value={selections[opt.id] ?? null}
358	                onChange={handleChange}
359	                saveStatus={savingOptions[opt.id]}
360	                disabled={locked}
361	              />
362	            ))}
363	          </div>
364	        );
365	      })}
366	
367	      {/* Ungrouped options */}
368	      {optionsByGroup["__ungrouped"] && optionsByGroup["__ungrouped"].length > 0 && (
369	        <div className="space-y-3">
370	          {optionsByGroup["__ungrouped"]
371	            .filter((opt) => isDependencySatisfied(opt))
372	            .map((opt) => (
373	              <OptionField
374	                key={opt.id}
375	                option={opt}
376	                value={selections[opt.id] ?? null}
377	                onChange={handleChange}
378	                saveStatus={savingOptions[opt.id]}
379	                disabled={locked}
380	              />
381	            ))}
382	        </div>
383	      )}
384	
385	      {/* Done button */}
386	      {!locked && (
387	        <div className="pt-4">
388	          <button
389	            type="button"
390	            disabled={!allRequiredDone || anySaving}
391	            onClick={() => router.push("/")}
392	            className={`w-full rounded-2xl px-4 py-4 font-semibold text-base transition-colors ${
393	              allRequiredDone && !anySaving
394	                ? "bg-green-600 text-white hover:bg-green-700 active:bg-green-800"
395	                : "bg-gray-200 text-gray-400 cursor-not-allowed"
396	            }`}
397	          >
398	            {anySaving
399	              ? "Saving…"
400	              : allRequiredDone
401	              ? "I'm all done"
402	              : `${requiredIncomplete.length} required ${requiredIncomplete.length === 1 ? "option" : "options"} left`}
403	          </button>
404	          <p className="text-xs text-gray-400 text-center mt-2">
405	            Your selections are saved automatically. You can come back and change them anytime before the deadline.
406	          </p>
407	        </div>
408	      )}
409	    </div>
410	  );
411	}
412	
413	// ---------------------------------------------------------------------------
414	// Individual option field component
415	// ---------------------------------------------------------------------------
416	
417	function OptionField({
418	  option,
419	  value,
420	  onChange,
421	  saveStatus,
422	  disabled,
423	}: {
424	  option: Option;
425	  value: SelectionValue;
426	  onChange: (optionId: string, value: SelectionValue, debounce?: boolean) => void;
427	  saveStatus?: "saving" | "saved" | "error";
428	  disabled: boolean;
429	}) {
430	  return (
431	    <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-4">
432	      {/* Save indicator */}
433	      <div className="flex items-start justify-between mb-1">
434	        <div className="flex items-start gap-3 flex-1 min-w-0">
435	          {option.icon && (
436	            <div className="w-8 h-8 rounded-lg bg-green-50 text-green-600 flex items-center justify-center shrink-0">
437	              <OptionIcon iconKey={option.icon} className="w-5 h-5" />
438	            </div>
439	          )}
440	          <div className="flex-1 min-w-0">
441	          <div className="flex items-center gap-1.5">
442	            <span className="font-semibold text-gray-900">{option.name}</span>
443	            {option.is_required && <span className="text-red-500 text-sm">*</span>}
444	            {(option.option_type === "checkbox" || option.option_type === "trip_cost") && option.cost ? (
445	              <span className="text-green-700 font-semibold text-sm ml-1">
446	                ${Number(option.cost).toLocaleString()}
447	              </span>
448	            ) : null}
449	          </div>
450	          {option.description && (
451	            <div className="text-sm text-gray-500 mt-0.5 prose prose-sm prose-gray max-w-none">
452	              <ReactMarkdown remarkPlugins={[remarkBreaks]}>{option.description}</ReactMarkdown>
453	            </div>
454	          )}
455	          </div>
456	        </div>
457	        <SaveIndicator status={saveStatus} />
458	      </div>
459	
460	      {/* Input based on type */}
461	      {(option.option_type === "checkbox" || option.option_type === "trip_cost") && (
462	        <CheckboxInput option={option} value={value} onChange={onChange} disabled={disabled} />
463	      )}
464	      {option.option_type === "select" && (
465	        <SelectInput option={option} value={value} onChange={onChange} disabled={disabled} />
466	      )}
467	      {option.option_type === "multi_select" && (
468	        <MultiSelectInput option={option} value={value} onChange={onChange} disabled={disabled} />
469	      )}
470	      {option.option_type === "text" && (
471	        <TextInput option={option} value={value} onChange={onChange} disabled={disabled} />
472	      )}
473	      {option.option_type === "number" && (
474	        <NumberInput option={option} value={value} onChange={onChange} disabled={disabled} />
475	      )}
476	      {option.option_type === "quantity" && (
477	        <QuantityInput option={option} value={value} onChange={onChange} disabled={disabled} />
478	      )}
479	    </div>
480	  );
481	}
482	
483	// ---------------------------------------------------------------------------
484	// Save indicator
485	// ---------------------------------------------------------------------------
486	
487	function SaveIndicator({ status }: { status?: "saving" | "saved" | "error" }) {
488	  return (
489	    <span className="w-14 flex items-center justify-end gap-1 text-xs shrink-0">
490	      {status === "saving" && (
491	        <>
492	          <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
493	          <span className="text-gray-400">Saving</span>
494	        </>
495	      )}
496	      {status === "saved" && (
497	        <>
498	          <svg className="w-3.5 h-3.5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
499	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
500	          </svg>
501	          <span className="text-green-600">Saved</span>
502	        </>
503	      )}
504	      {status === "error" && (
505	        <>
506	          <svg className="w-3.5 h-3.5 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
507	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
508	          </svg>
509	          <span className="text-red-600">Error</span>
510	        </>
511	      )}
512	    </span>
513	  );
514	}
515	
516	// ---------------------------------------------------------------------------
517	// Checkbox input
518	// ---------------------------------------------------------------------------
519	
520	function CheckboxInput({
521	  option,
522	  value,
523	  onChange,
524	  disabled,
525	}: {
526	  option: Option;
527	  value: SelectionValue;
528	  onChange: (optionId: string, value: SelectionValue, debounce?: boolean) => void;
529	  disabled: boolean;
530	}) {
531	  const checked = value === true;
532	  return (
533	    <button
534	      type="button"
535	      disabled={disabled}
536	      onClick={() => onChange(option.id, !checked)}
537	      className={`mt-2 w-full flex items-center justify-between rounded-xl px-3 py-2.5 transition-colors ${
538	        disabled
539	          ? "bg-gray-50 cursor-not-allowed"
540	          : checked
541	          ? "bg-green-50 border border-green-200"
542	          : "bg-gray-50 hover:bg-gray-100 border border-transparent"
543	      }`}
544	    >
545	      <span className="text-sm text-gray-700">{checked ? "Selected" : "Tap to select"}</span>
546	      <div
547	        className={`w-10 h-6 rounded-full transition-colors relative ${
548	          checked ? "bg-green-600" : "bg-gray-300"
549	        } ${disabled ? "opacity-50" : ""}`}
550	      >
551	        <div
552	          className={`absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform ${
553	            checked ? "translate-x-[18px]" : "translate-x-0.5"
554	          }`}
555	        />
556	      </div>
557	    </button>
558	  );
559	}
560	
561	// ---------------------------------------------------------------------------
562	// Select (radio) input
563	// ---------------------------------------------------------------------------
564	
565	function SelectInput({
566	  option,
567	  value,
568	  onChange,
569	  disabled,
570	}: {
571	  option: Option;
572	  value: SelectionValue;
573	  onChange: (optionId: string, value: SelectionValue, debounce?: boolean) => void;
574	  disabled: boolean;
575	}) {
576	  const choices = option.choices || [];
