762	// Quantity input (per-choice numeric counters with optional shared cap)
763	// ---------------------------------------------------------------------------
764	
765	function QuantityInput({
766	  option,
767	  value,
768	  onChange,
769	  disabled,
770	}: {
771	  option: Option;
772	  value: SelectionValue;
773	  onChange: (optionId: string, value: SelectionValue, debounce?: boolean) => void;
774	  disabled: boolean;
775	}) {
776	  const choices = option.choices || [];
777	  const hasRow =
778	    value !== null && value !== undefined && typeof value === "object" && !Array.isArray(value);
779	  const map: Record<string, number> = hasRow
780	    ? (value as Record<string, number>)
781	    : {};
782	  const total = Object.values(map).reduce((a, b) => a + (Number(b) || 0), 0);
783	  const max = option.max_total ?? null;
784	  const atCap = max != null && total >= max;
785	  const optedZero = hasRow && total === 0;
786	
787	  const update = (choiceValue: string, next: number, debounce = false) => {
788	    const safe = Math.max(0, Math.floor(Number.isFinite(next) ? next : 0));
789	    const otherSum = total - (map[choiceValue] || 0);
790	    const clamped = max != null ? Math.min(safe, Math.max(0, max - otherSum)) : safe;
791	    const nextMap: Record<string, number> = { ...map };
792	    if (clamped <= 0) delete nextMap[choiceValue];
793	    else nextMap[choiceValue] = clamped;
794	    const hasAny = Object.keys(nextMap).length > 0;
795	    onChange(option.id, hasAny ? nextMap : null, debounce);
796	  };
797	
798	  return (
799	    <div className="mt-2 space-y-2">
800	      {max != null && (
801	        <div className="flex items-baseline justify-between text-xs px-1">
802	          <span className="text-gray-500">Total</span>
803	          <span className={`font-semibold tabular-nums ${atCap ? "text-amber-700" : "text-gray-700"}`}>
804	            {total} / {max}
805	          </span>
806	        </div>
807	      )}
808	      {choices.map((choice) => {
809	        const qty = map[choice.value] || 0;
810	        const decDisabled = disabled || qty <= 0;
811	        const incDisabled = disabled || (max != null && total >= max);
812	        return (
813	          <div
814	            key={choice.value}
815	            className={`flex items-center justify-between gap-2 rounded-xl px-3 py-2 ${
816	              qty > 0
817	                ? "bg-green-50 border border-green-200"
818	                : "bg-gray-50 border border-transparent"
819	            } ${disabled ? "opacity-60" : ""}`}
820	          >
821	            <span className="text-sm text-gray-800 truncate">{choice.label}</span>
822	            <div className="flex items-center gap-1.5 shrink-0">
823	              <button
824	                type="button"
825	                disabled={decDisabled}
826	                onClick={() => update(choice.value, qty - 1)}
827	                className={`w-8 h-8 rounded-full font-semibold text-lg leading-none flex items-center justify-center ${
828	                  decDisabled
829	                    ? "bg-gray-100 text-gray-300 cursor-not-allowed"
830	                    : "bg-white border border-gray-300 text-gray-700 active:bg-gray-100"
831	                }`}
832	                aria-label={`Decrease ${choice.label}`}
833	              >
834	                −
835	              </button>
836	              <input
837	                type="number"
838	                inputMode="numeric"
839	                min={0}
840	                max={max ?? undefined}
841	                value={qty === 0 ? "" : qty}
842	                disabled={disabled}
843	                onChange={(e) => {
844	                  const raw = e.target.value;
845	                  update(choice.value, raw === "" ? 0 : Number(raw), true);
846	                }}
847	                placeholder="0"
848	                className="w-12 text-center rounded-lg border border-gray-200 bg-white px-1 py-1 text-sm tabular-nums focus:outline-none focus:ring-2 focus:ring-green-500"
849	              />
850	              <button
851	                type="button"
852	                disabled={incDisabled}
853	                onClick={() => update(choice.value, qty + 1)}
854	                className={`w-8 h-8 rounded-full font-semibold text-lg leading-none flex items-center justify-center ${
855	                  incDisabled
856	                    ? "bg-gray-100 text-gray-300 cursor-not-allowed"
857	                    : "bg-white border border-gray-300 text-gray-700 active:bg-gray-100"
858	                }`}
859	                aria-label={`Increase ${choice.label}`}
860	              >
861	                +
862	              </button>
863	            </div>
864	          </div>
865	        );
866	      })}
867	      {option.is_required && (
868	        <button
869	          type="button"
870	          disabled={disabled}
871	          onClick={() => onChange(option.id, optedZero ? null : {})}
872	          className={`mt-1 w-full flex items-center gap-2.5 rounded-xl px-3 py-2.5 text-sm transition-colors ${
873	            optedZero
874	              ? "bg-green-50 border border-green-200 text-gray-800"
875	              : "bg-gray-50 border border-transparent text-gray-700 hover:bg-gray-100"
876	          } ${disabled ? "opacity-60 cursor-not-allowed" : ""}`}
877	        >
878	          <span
879	            className={`w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 ${
880	              optedZero ? "border-green-600 bg-green-600" : "border-gray-300"
881	            }`}
882	          >
883	            {optedZero && (
884	              <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
885	                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
886	              </svg>
887	            )}
888	          </span>
889	          <span>I&apos;m not having any</span>
890	        </button>
891	      )}
892	    </div>
893	  );
894	}
