155	/**
156	 * Sync `contest_participants` based on cost_item linkages — issue #124.
157	 *
158	 * Today's `syncContestEnrollment` (above) wires options → contests directly
159	 * via `trip_options.linked_contest_id` / `choices[].contest_id`. The newer
160	 * model wires options → cost_items → contests, where:
161	 *   - `cost_items.linked_option_id` says which option funds the cost item
162	 *   - `cost_item_option_choices(choice_value)` filters to specific choices
163	 *     (empty rows = funded by any non-zero selection on the option)
164	 *   - `contests.buy_in_cost_item_id` says which cost_item bankrolls the contest
165	 *
166	 * When a user changes their selection on `optionId`, this resolves every
167	 * cost_item that fundable from that option, decides whether the user's value
168	 * funds it, and upserts/deletes contest_participants for every contest whose
169	 * buy-in cost_item matches.
170	 *
171	 * Idempotent. Can run alongside `syncContestEnrollment` — they upsert the
172	 * same composite key with no conflicts.
173	 */
174	export async function syncCostItemContestEnrollment(
175	  adminClient: SupabaseClient,
176	  userId: string,
177	  optionId: string,
178	  value: unknown,
179	): Promise<void> {
180	  const { data: items } = await adminClient
181	    .from("cost_items")
182	    .select("id, choices:cost_item_option_choices(choice_value)")
183	    .eq("linked_option_id", optionId);
184	  if (!items || items.length === 0) return;
185	
186	  for (const item of items as Array<{ id: string; choices?: { choice_value: string }[] | null }>) {
187	    const choices = item.choices || [];
188	    const fundsThis = (() => {
189	      if (choices.length === 0) return isYesValue(value);
190	      const choiceSet = new Set(choices.map((c) => c.choice_value));
191	      if (Array.isArray(value)) return (value as unknown[]).some((v) => typeof v === "string" && choiceSet.has(v));
192	      if (typeof value === "string") return choiceSet.has(value);
193	      // checkbox `true` against a choice-filtered cost_item is a config bug —
194	      // we treat it as funded so admins notice rather than silently skip.
195	      return value === true;
196	    })();
197	
198	    const { data: contests } = await adminClient
199	      .from("contests")
200	      .select("id, contest_type")
201	      .eq("buy_in_cost_item_id", item.id);
202	    if (!contests || contests.length === 0) continue;
203	
204	    for (const c of contests as Array<{ id: string; contest_type: string }>) {
205	      if (fundsThis) {
206	        await adminClient
207	          .from("contest_participants")
208	          .upsert(
209	            { contest_id: c.id, user_id: userId },
210	            { onConflict: "contest_id,user_id" },
211	          );
212	
213	        // Pickem stores paid status on `pickem_payments`. When a Loozer
214	        // funds the contest via their option selection, the trip ledger
215	        // collects from them automatically — mark them paid up front.
216	        // Manual accordion adds bypass this and require a separate
217	        // Venmo + admin toggle.
218	        if (c.contest_type === "pickem") {
219	          await adminClient
220	            .from("pickem_payments")
221	            .upsert(
222	              {
223	                contest_id: c.id,
224	                user_id: userId,
225	                paid: true,
226	                paid_at: new Date().toISOString(),
227	              },
228	              { onConflict: "contest_id,user_id" },
229	            );
230	        }
231	      } else {
232	        await adminClient
233	          .from("contest_participants")
234	          .delete()
235	          .eq("contest_id", c.id)
236	          .eq("user_id", userId);
237	
238	        // Mirror un-enroll: drop the auto-paid mark when the user
239	        // deselects the option.
240	        if (c.contest_type === "pickem") {
241	          await adminClient
242	            .from("pickem_payments")
243	            .delete()
244	            .eq("contest_id", c.id)
245	            .eq("user_id", userId);
246	        }
247	      }
248	    }
249	  }
250	}
251	
252	function isYesValue(value: unknown): boolean {
253	  if (value === true) return true;
254	  if (typeof value === "string") return value !== "" && value !== "none";
255	  if (Array.isArray(value)) return value.length > 0;
256	  if (typeof value === "number") return value > 0;
257	  return false;
258	}
